export const REPO_VIEW = ["repo", "view", "--json", "nameWithOwner"];
export const VIEW_ARGS = [
  "issue",
  "view",
  "5",
  "--repo",
  "other/repo",
  "--json",
  "title,body",
];

export const reply = (stdout: string, code = 0, stderr = ""): RunResult => ({
  stdout,
  stderr,
  code,
});

/** gh's answer to `repo view` for the checkout this repository is. */
export const repoName = reply(
  JSON.stringify({ nameWithOwner: "corekraft/kore" }),
);

/** gh's answer to `issue view`: the issue's title and body as JSON. */
export const view = (title: string, body: string): RunResult =>
  reply(JSON.stringify({ title, body }));

/** The arguments of `issue create` for the checkout's repository. */
export const createArgs = (repo: string, title: string) => [
  "issue",
  "create",
  "--repo",
  repo,
  "--title",
  title,
  "--body-file",
  "-",
];

/** The arguments of `issue edit` for issue 5 of other/repo. */
export const editArgs = (title: string) => [
  "issue",
  "edit",
  "5",
  "--repo",
  "other/repo",
  "--title",
  title,
  "--body-file",
  "-",
];
